from wcommon import dims_G, dims_M, legend, notes, head, sched
LAYER = "E-FRESH"
ROWS=[(lambda s,x,y: s.device_dot(x,y,0.14,letter="AF"), "معطر جو أوتوماتيكي 300 مل ببطارية - تعليق 2.10 م", "automatic air freshener dispenser"),
      (lambda s,x,y: s.circle(x,y,0.3,lw=5), "نطاق التغطية ~ 40 م²", "coverage ~40 m²")]
def _d(s,floor,pts):
    for p in pts: s.device_dot(*p,0.16,cover=2.5,letter="AF")
    (dims_G if floor=="G" else dims_M)(s,pts)
    legend(s,floor,"رموز معطر الجو - LEGEND",ROWS)
    sched(s,floor,"جدول معطر الجو",["البند","المواصفة","العدد"],[("AF","معطر أوتوماتيكي LCD قابل للبرمجة 7.5/15/30 دقيقة، عبوة 300 مل",f"{len(pts)}"),("تعليق","2.10 م على الجدار، بعيداً عن مخارج التكييف","-"),("عبوات","استهلاك شهري تقريبي",f"{len(pts)} عبوة")])
    notes(s,floor,["الأجهزة بالحمامات تبرمج على 7.5 دقيقة، وبالجلسات على 30 دقيقة برائحة خفيفة موحدة.","لا تركب الأجهزة فوق الطاولات أو قرب أجهزة الطهي.","الأبعاد الحمراء: موقع كل جهاز عن الجدران."],"ملاحظات")
def draw_G(s): _d(s,"G",[(12.2,35.3),(14.2,39.6),(10.5,43.4)]); head(s,"G","مخطط معطر الجو - الدور الأرضي: المدخل، صالة الانتظار، نهاية الكاونتر.")
def draw_M(s): _d(s,"M",[(1.0,25.2),(6.0,25.2),(9.0,25.2),(0.3,17.5),(8.5,18.5),(7.5,24.9),(9.0,23.5),(13.8,15.9)]); head(s,"M","مخطط معطر الجو - الميزانين: الحمامات الثلاثة، الجلسات، الممر، المكاتب، الاجتماعات.")
